#include "compiler.hpp"
#include "compiler_internal.hpp"

using blitz::types::type;
using namespace blitz::compiler_detail;

////////////////////////////////////////////////////////////////////////////////
// Order of evaluation
//
// The original compiler turns an expression into a tree and then walks it with a register allocator that labels every node with
// the number of registers it needs (a leaf needs 1, a node with two children needs one more than both if they need the same, else
// the larger one). The child that needs more is evaluated first, a tie goes to the left one. That is how `F(a, b, c)` evaluates
// b, c, a, and how `x + y * z` evaluates y * z first. Programs that call Rnd or read files several times in one expression depend
// on it. Calls take their arguments as a chain `(a1, (a2, (a3 ...)))`, which is where "the last two first, then the rest from
// right to left" comes from.
////////////////////////////////////////////////////////////////////////////////

std::string blitz::compiler::capture_code(std::function<void()> const& generate)
{
	if (_terminated) {
		_body << label("dead") << ":\n";
		_terminated = false;
	}
	code_buffer outer;
	outer.swap(_body);
	std::string code;
	try {
		generate();
		code = std::move(_body.text);
	} catch (...) {
		_body.swap(outer);
		throw;
	}
	_body.swap(outer);
	return code;
}

blitz::compiler::operand blitz::compiler::capture(ast::expression const* expr)
{
	operand o;
	o.code = capture_code([&] { o.v = gen(expr); });
	return o;
}

void blitz::compiler::place(std::string const& code)
{
	_body << code;
}

void blitz::compiler::place(std::string&& code)
{
	if (_body.text.empty()) {
		_body.text = std::move(code);
	} else {
		_body.text += code;
	}
}

// Puts the code of the arguments of a call in the order the original evaluated them. Returns the registers the call needs.
int blitz::compiler::place_sequence(std::vector<operand> const& operands)
{
	if (operands.empty()) {
		return 1;
	}
	if (sane_evaluation_order) {
		int need = operands.back().v.need;
		for (size_t idx = operands.size() - 1; idx-- > 0;) {
			need = pair_need(operands[idx].v.need, need);
		}
		for (auto const& o : operands) {
			place(o.code);
		}
		return need;
	}
	size_t              last  = operands.size() - 1;
	std::vector<size_t> order = { last };
	int                 need  = operands[last].v.need;
	for (size_t idx = last; idx-- > 0;) {
		int mine = operands[idx].v.need;
		if (right_first(mine, need)) {
			order.push_back(idx);
		} else {
			order.insert(order.begin(), idx);
		}
		need = pair_need(mine, need);
	}
	for (auto idx : order) {
		place(operands[idx].code);
	}
	return need;
}

// The registers an expression needs when nothing above set it: calls and operators take it from what they work on.
int blitz::compiler::default_need(ast::expression const* expr)
{
	auto known = [&](ast::expression const* e) {
		auto it = _needs.find(e);
		return (it == _needs.end()) ? 1 : it->second;
	};
	if (auto c = dynamic_cast<ast::call const*>(expr)) {
		if (c->arguments.empty()) {
			return 1;
		}
		int need = known(c->arguments.back().get());
		for (size_t idx = c->arguments.size() - 1; idx-- > 0;) {
			need = pair_need(known(c->arguments[idx].get()), need);
		}
		return need;
	} else if (auto u = dynamic_cast<ast::unary const*>(expr)) {
		return known(u->operand.get());
	} else if (auto f = dynamic_cast<ast::field_access const*>(expr)) {
		return known(f->object.get());
	} else if (auto i = dynamic_cast<ast::index_access const*>(expr)) {
		return known(i->index.get());
	}
	return 1;
}

// 0 for something that is evaluated, 1 for a constant and 2 for a number read from a variable. The original folds the last two
// into the instruction when they are the right operand (and for some operators the left), so they cost no register.
int blitz::compiler::direct_kind(ast::expression const* expr, value const& v)
{
	if (!is_number(v.type) && (v.type != type::STRUCT)) {
		return 0;
	}
	if (is_zero_constant(v.repr) || is_nonzero_constant(v.repr)) {
		return 1;
	}
	if (auto l = dynamic_cast<ast::literal const*>(expr)) {
		return (l->kind == ast::literal::variant::STRING) ? 0 : 1;
	}
	if (auto r = dynamic_cast<ast::reference const*>(expr)) {
		if (auto var = find(r->name)) {
			if (var->dims || var->count) {
				return 0;
			}
			return var->constant ? 1 : 2;
		}
	}
	return 0;
}

// Which operand of a binary operation goes first, and how many registers it needs.
void blitz::compiler::plan_binary(ast::binary const* node, operand const& lhs, operand const& rhs, bool& rhs_first, int& need)
{
	using op    = ast::binary::op;
	namespace t = blitz::types;

	int  ln = lhs.v.need, rn = rhs.v.need;
	auto generic = [&] {
		rhs_first = right_first(ln, rn);
		need      = pair_need(ln, rn);
	};
	rhs_first = false;
	generic();
	if (sane_evaluation_order) {
		rhs_first = false;
		return;
	}

	bool integers = t::is_integer(lhs.v.type) && t::is_integer(rhs.v.type);
	if (!integers || (node->kind == op::POWER)) {
		return; // Reals, strings and objects are all a call or a generic operation.
	}
	int ld = direct_kind(node->lhs.get(), lhs.v), rd = direct_kind(node->rhs.get(), rhs.v);

	// Folds `x op y` into one instruction that works on the left part, `ld`/`rd` being the part that is folded.
	auto left_only = [&] {
		rhs_first = false;
		need      = ln;
	};
	// The variable is read by the instruction after the other part was evaluated.
	auto right_only = [&] {
		rhs_first = (ld == 2);
		need      = rn;
	};

	auto power_of_two = [](std::string const& repr) {
		if (!is_nonzero_constant(repr)) {
			return false;
		}
		long long n = std::stoll(repr);
		return (n > 0) && ((n & (n - 1)) == 0);
	};

	switch (node->kind) {
	case op::ADD:
	case op::SUBTRACT:
	case op::MULTIPLY:
		if (node->kind == op::MULTIPLY && (rd == 1) && power_of_two(rhs.v.repr)) {
			left_only();
		} else if (node->kind == op::MULTIPLY && (ld == 1) && (rd != 1) && power_of_two(lhs.v.repr)) {
			right_only();
		} else if (rd != 0) {
			left_only();
		} else if ((node->kind != op::SUBTRACT) && (ld != 0)) {
			right_only();
		}
		break;
	case op::DIVIDE:
		if ((rd == 1) && power_of_two(rhs.v.repr)) {
			left_only();
		}
		break;
	case op::SHL:
	case op::SHR:
	case op::SAR:
		if (rd == 1) {
			left_only();
		}
		break;
	case op::EQUAL:
	case op::NOT_EQUAL:
	case op::LESS:
	case op::LESS_EQUAL:
	case op::GREATER:
	case op::GREATER_EQUAL:
		if (ld == 2) {
			if (rd == 1) {
				rhs_first = false;
				need      = 1;
			} else {
				right_only();
			}
		} else if (rd != 0) {
			left_only();
		}
		break;
	default:
		break; // Modulo is a call, and the logical operators are generic.
	}
}
